import{_ as r,a,b as l}from"./chunks/7f24e5be6ed40bb55618.zDQWPFo7.js";import{_ as o,C as i,o as n,c as s,j as e,a as u,E as m,a5 as h}from"./chunks/framework.DNkHA0lr.js";const x=JSON.parse('{"title":"令人不悦的真相：AI 正在冲着你的工作而来","description":"","frontmatter":{"title":"令人不悦的真相：AI 正在冲着你的工作而来","originalTitle":"The Unpleasant Truth: AI Is Coming For Your Job","date":"2025-05-13","originalUrl":"https://thedankoe.com/letters/the-unpleasant-truth-ai-is-coming-for-your-job/","minutes":14,"sourceHash":"3f014ff8d22a4887ec29eb101f8e39b7e7e8232f4ad25423f1353b0dc5775b6e","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-unpleasant-truth-ai-is-coming-for-your-job/"}]]},"headers":[],"relativePath":"letters/the-unpleasant-truth-ai-is-coming-for-your-job.md","filePath":"letters/the-unpleasant-truth-ai-is-coming-for-your-job.md"}'),c={name:"letters/the-unpleasant-truth-ai-is-coming-for-your-job.md"};function A(I,p,b,f,d,g){const t=i("ArticleMeta");return n(),s("div",null,[p[0]||(p[0]=e("h1",{id:"令人不悦的真相-ai-正在冲着你的工作而来",tabindex:"-1"},[u("令人不悦的真相：AI 正在冲着你的工作而来 "),e("a",{class:"header-anchor",href:"#令人不悦的真相-ai-正在冲着你的工作而来","aria-label":'Permalink to "令人不悦的真相：AI 正在冲着你的工作而来"'},"​")],-1)),m(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/vFgjDSySYo8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>目前最顶尖的 AI 模型比 85% 的人类还聪明。</p><p>到 2026 年底，它将比 99.9% 的人类还聪明。</p><p>你还以为自己能保住工作？</p><p>以上这段话来自 <a href="https://x.com/davidpattersonx/status/1920227618856583355" target="_blank" rel="noreferrer">David Patterson 在 X 上的发帖</a>，埃隆·马斯克（Elon Musk）对此回复道：</p><p>“大致正确”</p><p>现在，让我再往你脑子里塞点信息，让它超载一下。</p><p>上个月，Fiverr 的 CEO 给他的团队发了一封邮件。</p><p><img src="'+r+'" alt=""></p><p>虽然我猜测 Fiverr 是个特例，毕竟大多数 Fiverr 上的工作质量还停留在上一代 AI 水平（说这话可能得挨骂），但邮件中有几个值得关注的要点：</p><ul><li>令人不悦的真相：AI 正在冲着你的工作而来，也冲着他的工作而来，冲着所有工作而来</li><li>简单的任务不再存在，困难的任务变成了新的简单任务，而不可能完成的任务则变成了困难任务</li><li>对着枕头大喊一声，重新振作起来，让自己具备应对未来的能力（我们将在这篇文章中学到怎么做）</li></ul><p>除此之外，Shopify 的 CEO、Duolingo 这家公司，以及我在社交媒体上看到的更多企业，都公开表示他们正在采用“AI 优先”的思维方式。已经有一些头条新闻报道 <a href="https://www.usatoday.com/story/tech/news/2025/04/30/duolingo-ai-first-contract-workers-replaced/83366078007/" target="_blank" rel="noreferrer">Duolingo 用 AI 替换员工</a> 的消息。</p><p>现在被吓到了吗？</p><p>很多人都被吓到了。</p><p>虽然我无法在这一篇文章里把我所有的想法都讲完，但我会分享一些，让你现在就能做点什么，为即将到来的变化做好更充分的准备。</p><p>这是活在当下最令人兴奋的时代之一。</p><p>读完这篇文章后，我相信你也会有同样的感受。</p><h2 id="成为-ai-优先-的人" tabindex="-1">成为“AI 优先”的人 <a class="header-anchor" href="#成为-ai-优先-的人" aria-label="Permalink to &quot;成为“AI 优先”的人&quot;">​</a></h2><p>面对 AI，人可以分成三种类型：</p><ul><li>那些几年前试过一次 ChatGPT，觉得没什么特别的人</li><li>那些用各种 AI 工具做网络搜索、摘要总结、以及那些不用 AI 也顶多多花十秒钟就能完成的简单任务的人</li><li>那些已经用得够多、“看到了光”，并在一切可能的场合都在使用 AI 的人</li></ul><p>我对 AI 有很多看法。</p><p>我完全不认为它会削弱你思考的能力。</p><p>我也不认为它会限制你的创造力或个人发展。</p><p>但我希望这篇文章主要还是偏实用一些。</p><p>大多数人不明白的是：AI 的产出上限取决于你的技能和想象力。</p><p>如果你给 AI 极其具体的指令，或者使用一个专门为你完成这类事情的、ChatGPT 之外的应用，它会相当精准地遵照那些指令去执行。</p><p>举个例子：普通的 AI 用户可能因为懒惰或者缺乏了解，直接输入“帮我做一个 YouTube 视频”。AI 会回复几个问题，然后基于网上一堆糟糕的 YouTube 建议（这种建议网上太多了）吐出一份脚本，这对你根本没什么帮助。尤其是因为任何人都能这么做。</p><p>相反，我可以给它非常精确的指令，比如：</p><ul><li>如何根据我的兴趣和专长生成高表现的创意</li><li>如何设计能瞬间抓住观众的完美开场</li><li>如何构建正文结构、语气、风格、语调，以及在哪里插入 B-roll、画面、引用或其他内容</li><li>我可以继续举例，但你已经明白意思了</li></ul><p>然后，我可以针对任何风格的视频、社交媒体帖子、落地页，或者其他几乎任何任务重复这个流程……于是我就有了一个提示词（也就是“员工”）数据库，它们能带着<em>我的专业知识和创造力</em>，在几秒钟内完成本该花上数小时、数天甚至数周的工作。</p><p>这是我向 AI 询问某期通讯（newsletter）可能标题变体时的一个例子：</p><p><img src="'+a+'" alt=""></p><p>而这是我使用自己的 <a href="https://app.kortex.co/public/document/917056b7-26b3-47d6-9d5b-12e700a2c890" target="_blank" rel="noreferrer">标题生成提示词</a> 时得到的结果：</p><p><img src="'+l+'" alt=""></p><p>最先出来的那 10 个标题一般，主要是因为它是从引言部分抽取内容，而不是从整篇通讯的宏观理念出发，所以我还需要打磨提示词。但即便如此，质量已经高出许多。</p><p>我们目前正在 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 中构建一个自定义提示词和工作流功能，让你能拥有一个装满自己独有流程的工作空间。如果你现在想看看这个 YouTube 案例是怎么实际运作的，<a href="https://youtu.be/4E9rO6FDUwo" target="_blank" rel="noreferrer">点这里观看</a>。它把一段视频脚本写得多好，会让你大吃一惊。</p><p>让 AI 执行这类具体任务，只是其中一种用法而已。</p><p>更进一步说，当你把 AI 当作思考伙伴使用时，你思考的方式本身就会开始改变，因为你在每一次输出中都在阅读和学习更多东西。这会影响你的决策，而你的决策又会以复利的方式叠加，塑造出你人生的结果。影响巨大。</p><h3 id="试着把自己-自动化-出工作岗位" tabindex="-1">试着把自己“自动化”出工作岗位 <a class="header-anchor" href="#试着把自己-自动化-出工作岗位" aria-label="Permalink to &quot;试着把自己“自动化”出工作岗位&quot;">​</a></h3><blockquote><p>成为“AI 原生”并不是为你的用户开发新功能。它是一种运营公司的方式。它关乎你如何工作、如何思考，你和你的公司如何“呼吸”。这是一场重新架构，一次重新布线，是一种哲学层面的转变：从“我们如何扩展人力？”转变为“我们如何借助机器扩展决策、创造力和行动力？”</p><p>——Signull</p></blockquote><p>促使我写这篇文章的，是一系列想法的累积，其中有几个想法把我推过了那道必须动笔的临界点。</p><p>第一个想法，来自 Cosmos Institute 提出的“<em><a href="https://substack.com/home/post/p-163203331" target="_blank" rel="noreferrer">自我主导的职业生涯</a></em>”这一概念。</p><p>在工业化之前，自由的个体大多是农民和手工艺者。</p><p>自由人的标志，就是他们本应依照自己的兴趣行事，一生中做很多不同的事情。大约 80% 的自由劳动者是自雇者，而如今这个比例仅有 10%。</p><p>而奴隶，则是那些被训练一生只做一件特定任务的人。</p><p>随着机器的出现，我们很快就发现自己被困在了工厂、Excel 表格和各种算法之中。</p><p>那么问题来了：</p><p><em>这场 AI 革命，会不会进一步剥夺我们依照自身兴趣行事的自主权和自由？</em></p><p>完全有可能：大多数人会从“自动驾驶”滑向“自动补全”。从被分配工作，变成工作直接被替他们完成。</p><p>但对于那些重视创造性工作、想要掌控自己所做选择的人来说，还有另一种选择。</p><p>通常，在技术转型时期，人类会通过发展更高层次的技能和知识形式来适应变化。当某些技能因自动化而必然贬值时，我们就会向上抽象一层。</p><p>在 AI 面前，这一切正在再次发生。我们必须超越那些过去几十年一直服务良好的大多数技能，再向上抽象一层。具体来说，我们正在从“体力/劳作”转向“心智”。</p><p>既然 AI 现在的思考和执行能力已经和我们不相上下，我们就必须<em>思考我们自己是如何思考的</em>，去审视那些<em>本可以</em>替我们思考的系统。</p><p>在我们继续往下讲之前，请记住这个问题：</p><p><em>我什么时候该借助 AI 的杠杆，什么时候该亲自动手？</em></p><p>这就引出了关于“AI 优先”的第二个想法：</p><p><a href="https://substack.com/@signull/p-160784620" target="_blank" rel="noreferrer">在最近一篇文章</a> 中，我最喜欢的一位匿名思考者 Signull 举例说明了在典型的公司角色中，“AI 优先”会是什么样子。</p><p>下面是几个直接摘自他文章的例子，我就不做过多改动，以免曲解原意。</p><p><strong>在产品开发方面：</strong></p><p><em>非 AI 优先：</em></p><ul><li>反馈循环缓慢</li><li>人工调研</li><li>基于个人意见展开的路线图争论</li></ul><p><em>AI 优先</em></p><ul><li>几分钟内总结所有用户访谈</li><li>基于功能聚类生成路线图选项</li><li>在任何东西上线之前先模拟用户行为</li></ul><p><em>提示词示例：</em></p><blockquote><p>“总结最近 50 份用户访谈，按照频率和强度对主要痛点进行归类。给出 3 个信噪比最高的产品方向建议。”</p><p>“根据用户反馈和使用数据，为一个全新的新手引导流程撰写产品规格文档。请包含边缘情况和反方论点。”</p></blockquote><p><strong>在客户支持方面：</strong></p><p><em>非 AI 优先：</em></p><ul><li>人工分诊</li><li>客服重复回答同样的问题</li></ul><p><em>AI 优先：</em></p><ul><li>利用 24/7 在线的大语言模型自动解决一级问题</li><li>为需要人工升级处理的复杂对话线程做总结</li><li>根据工单量动态生成帮助中心内容</li></ul><p><em>提示词示例：</em></p><blockquote><p>“总结这段包含 5 条消息的支持对话，并给出正确的解决方案建议。请标注出任何客户不满情绪。”</p><p>“为这个反复出现的问题生成一篇帮助中心文章。请包含截图、边缘情况，以及针对错误的提示说明。”</p></blockquote><p>现在想象一下，把这种做法用在市场营销或内容发布前的模拟测试上，用在基于用户画像的销售流程上，或者用在基于用户困惑点的设计变体上。这同样适用于一人公司或创作者。</p><p>常见的反对意见是：“AI 还没到那个水平呢”，但这恰恰就是重点所在。</p><p>它总会到那个水平的。</p><p>而一旦它到达那个水平，那些早已花时间钻研 AI 的人，会把你远远甩在后面，绕着你转圈跑。</p><p>就算它暂时还没到那个水平，学习 AI 依然是一件非常值得做的事。它显然将会成为我们生活中的重要组成部分。</p><p>那么，你该如何从现在开始行动，好让自己在那个转折点很快到来时已经准备就绪？</p><p>我的建议是：<em>练习把自己从工作中“自动化”出去。</em></p><p>当你去做<em>任何</em>一项任务时，试着这样做：</p><ul><li>像在教别人如何做你的工作一样，把整个流程详细写下来（<em>包括你的思考过程或创作过程</em>）</li><li>假设那个流程中的任何任务或环节都可以用一段提示词来完成</li><li>尝试把那个任务或环节转化为一段提示词</li><li>测试它，记录下它表现不好的地方，然后不断打磨这段提示词，直到它至少能达到 90% 的效果</li><li>把这段提示词妥善保存起来</li></ul><p>如果你根本不知道该如何完成某项任务，你可以直接问 AI 完成它的最佳方法，或者让 AI 拆解一段专家讲授该任务的 YouTube 视频，又或者把一本相关书籍交给 AI 做同样的事。然后，把这些内容转化成提示词，再不断打磨。</p><p>你作品的质量，取决于你提示词的质量。</p><p>并不是 AI 不如你厉害，而是你还不够厉害，无法让 AI 变得和你一样厉害。这是“任务思维”和“系统思维”之间的差别。</p><p>如今已经不再只是“一人企业”了。而是“一个人加上由书面指令诞生出来的员工”。（或者说，一小群人却能完成相当于 10 名员工的工作量。）</p><p>如今，我生命中最宝贵的东西之一，就是拥有一段<em>能生成提示词的提示词</em>。听起来挺滑稽，但它真的太神了。我可以随手写下一些简单的指令，把它喂给那段提示词，然后读一读输出结果，再加以打磨。</p><p>如果你想试试这个方法，去 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 里的 Chat → “Write Incredible AI Prompts”，动手玩一玩吧。</p><p>当然，成为“AI 优先”并不是唯一能让你免于被大规模替代的方法。</p><p>我们来谈谈另一件事。</p><h2 id="你可能得彻底改变自己的整个人生-而这其实是个大好消息" tabindex="-1">你可能得彻底改变自己的整个人生，而这其实是个大好消息 <a class="header-anchor" href="#你可能得彻底改变自己的整个人生-而这其实是个大好消息" aria-label="Permalink to &quot;你可能得彻底改变自己的整个人生，而这其实是个大好消息&quot;">​</a></h2><p>事情是这样的。</p><p>我没有资格去告诉那些我并不了解其人生的人，他们应该怎么做、应该怎么想。</p><p>我没有孩子要养。我不用同时打两份工来维持生计。我只是一个 28 岁的普通人，没什么资产，每天晚上都在外面吃饭（虽然我确实按时缴税）。</p><p>对那些人——我猜他们大概也不会读到这篇文章——我很抱歉，但我实在不知道该怎么帮你们。也许下面的内容至少能给你一些可以尝试的东西。</p><p>而对于那些认为解决之道应该是社会改革，而不是继续加速版的“朝九晚五”老鼠赛跑的人：</p><p>我同意。但你想要的那种无休止、免于工作的热带假期梦想是一种妄想,并不会让你幸福。我们之前已经多次讨论过,无论涉及多少钱,有意义的工作都是必要的(比如<a href="https://thedankoe.com/purpose" target="_blank" rel="noreferrer">在我的书里</a>)。生活是一种振荡。工作平衡休息,才能维持健康的心理状态。你对工作的定义和联想,可能和我的大不相同。</p><p><em>为比自己更宏大的事物做出贡献</em>,是幸福的一块重要拼图。这暗示着一种更成熟的工作定义。</p><p>但对大多数读到这篇文章的人来说——只要放下手机就能挤出几个小时,也不至于被赶出家门,生活总体上还算舒适——</p><p>问题出在哪儿?</p><p>你在抱怨什么?</p><p>即便这话已经被说烂了,而且不知怎么还能引发争议,但<em>普通</em>的朝九晚五工作真的糟糕透了(我说的不是那.01%可以在谷歌睡眠舱里打盹的人)。我们已经集体讨厌了它们几十年。进化解决问题,而现在我们解决了其中最痛苦的一个,你没资格再抱怨。</p><p>你面前摆着一生中最大的机遇之一,而你却还在掉进最俗套的陷阱里——贪图舒适,扮演受害者,试图死死抓住你那早已注定不会永久的旧生活方式?</p><p>你还没意识到,如果你做的工作是一台机器就能自动化完成的,那你的生活大概缺乏新奇、持续的成长、挑战和复杂性吗?光这一点就是一个巨大的信号,提示你该去做点新的事情了。这不是观点,这是被记录在案的心理发展规律。先满足基本需求,再追求自我实现的需求,而AI能同时加速这两者的进程。</p><p>对于那些已经被充分说服的人,你需要开始行动、开始构建了。</p><p><strong>1)剩下的,是精通与意义</strong></p><p>你还有几年的时间,之后你会被裁掉、或者暂时保住工作(但最终也会被裁掉)、或者不断升级技能以在你所在的公司里承担新的角色,或者只能自己想办法谋生。</p><p>AI不只是冲着艺术家和程序员来的,它冲的是任何拥有大脑的人。</p><p>现在,我相信这会创造一个我们不必再为钱发愁的世界。但我对此有所怀疑,因为人性这种东西……</p><p>但会有一个适应期,很多人在这段时间里不知道该做什么。</p><p>这就给我们留下了一个以精通和意义为核心的经济体。</p><p>换句话说,就是去发现并追求你一生的事业(你知道的,那件你本来就可以做、也本来就应该一直在做的事)。</p><p>我不知道我们将来会在VR里还是在火星上做这件事,但眼下,这件事是在互联网上完成的。</p><ul><li>选择一件你深切关心的事</li><li>以AI优先的思维方式,毫不留情地去研究、学习、精通它</li><li>毫不羞怯地公开分享你所知道的、你所做的,以及你为什么这么做</li></ul><p>因为在当今这个世界上,唯一真正的安全网,就是一份让人无法忽视的作品集。</p><p>这就引出了下一点:</p><p><strong>2)注意力是唯一的差异化因素</strong></p><p>随着这个世界被越来越多的AI填满——信任、注意力和信号会变得越来越稀缺。</p><p>是的,死气沉沉的互联网正在扩张。</p><p>任何人只需一个提示词,就能让AI批量生产出一年的内容。</p><p>但从前面的例子来看,这其实没什么大意义。</p><p>这只意味着市场的成熟度会持续快速提升。人们会厌倦千篇一律的模板,而这个模板还会每个月都变一次。人们会对大部分内容失去信任。而且这还没算上一个事实:你仍然得知道自己在做什么,才能让AI创造出独特而有吸引力的东西。</p><p>我的建议是:</p><ul><li>把AI用在那些你作为一人企业不想亲自去做的事情上。</li><li>不要把你深切关心的事情完全交给AI控制(不要让它代替你去做这项工作)。</li></ul><p>我喜欢写作。AI能写得不错,如果非写作者需要通过写作在其他领域实现自己一生的事业,我也鼓励他们把AI用在这个用途上,但如果让AI代替<em>我</em>去写,输出的东西就不是出自我的脑子。</p><p>既然我想专注于写作,我打算把AI用在维持写作所需的其他事情上,比如营销、销售、行政等等。那些我随着时间不断打磨的提示词,<em>就是</em>我的小员工。</p><p>这不是不真实,这是规模化的真实性。</p><p>因为从来没有哪个时代,一个人能以一整家公司的规模去运作。</p><p>这意味着什么?</p><p>这意味着你就是那个细分领域。</p><p>你就是那个差异化因素。</p><p>你的精通、你的经验,以及你透过一生中处理过的每一点信息所锻造出的独特世界观。</p><p>当AI让90%的产品变得千篇一律时,其实什么都没变。</p><p>人们仍然会从他们认识、信任、关注的人和品牌那里购买东西。</p><p>这与其说是在搭建销售漏斗,不如说是在构建一个人们可以去探索的世界。</p><p>我写过一篇关于<a href="https://open.substack.com/pub/thedankoe/p/how-to-build-a-world-the-2-hour-content?r=of0ip&amp;utm_campaign=post&amp;utm_medium=web&amp;showWelcomeOnShare=true" target="_blank" rel="noreferrer">如何构建一个世界</a>的文章,在这里。</p><p><strong>3)1000个真粉丝理论,越来越有现实意义</strong></p><p>大多数人并不想成名。</p><p>即便你想,也先把这个目标搁一搁,等你真正能靠自己养活自己再说。</p><p>这才是大多数人真正想要的。</p><p>而且你根本不需要数百万粉丝才能接近这个目标。</p><p>你大概只需要1000个真粉丝。</p><p>说实话,甚至比这还要少。</p><p>如果你擅长自己所做的事,你可以:</p><ul><li>每位客户收取5000美元来提供某项服务</li><li>为付费通讯收取10美元(是的,我现在也搭上了Substack这股风潮)</li><li>为任何类型的产品收取50到150美元不等的费用</li><li>创造衍生产品,比如一本书或一款软件(因为任何人都能编写出解决特定问题的应用),让买家反复购买</li></ul><p>大多数人靠每月5000到10000美元就能过得相当不错。如果你凭纯粹的技能和练习都做不到这一点……我也不知道该跟你说什么了。</p><p>以10美元的订阅费来说,花1到2年时间——这完全是可以做到的——培养出500个订阅者,就是每月5000美元(考虑到大约30%的人会选择按年付费,实际数字很可能是这个的两倍)。</p><p>如果你有一套产品组合——一个持续性的、一个高价的、以及各种低价产品——想靠做自己喜欢的事养活自己,其实真的不需要太多东西。</p><p>而且考虑到注意力在社交媒体上是如何流动的,人们又是如何不断去关注新的人,以及局外人看不到的各种自然波动,可分配的注意力其实完全足够。</p><p>关键在于,你要以与“上班”完全相反的方式来对待它。</p><p>这是一种不断演变的工作。这是一种要求持续学习的工作。这是一种有前提条件的工作——前提是你至少已经把自己的生活理出了一些头绪。</p><p>你一旦停滞不前,熵增便随之而来,而这其实是件美妙的事。</p><p>原地不动,才是美好生活的头号敌人。</p><p>—— Dan</p><p>当你准备好了,以下是我能进一步提供帮助的几种方式:</p><ul><li>这个Substack的付费档明天将涨价30%,如果你想锁定现在的价格,现在就是时候。随着越来越多的超级指南、提示词和行动计划加入其中,价格还会继续上涨。<a href="https://thedankoe.substack.com/p/mega-guide-how-to-create-your-first" target="_blank" rel="noreferrer">这是最新的一份超级指南,你可以看看它是否值10美元。</a></li><li>每周六,我都会给我个人邮件列表上超过175,000人发送一份高信号密度的写作精华摘要。如果你想收到它,<a href="https://thedankoe.com/letters" target="_blank" rel="noreferrer">可以在这里订阅。</a></li><li>如果你想把所有AI模型集中在一个地方,快速引用文档和PDF,并使用25个以上预先构建的学习、写作、营销和规划工作流——<a href="https://kortex.co/" target="_blank" rel="noreferrer">在这里免费注册Kortex。</a></li></ul><hr><p><a href="/en/letters/the-unpleasant-truth-ai-is-coming-for-your-job">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',157))])}const T=o(c,[["render",A]]);export{x as __pageData,T as default};
